body:
I've tried it with all 4 of the variations below, with and without the ConnectFlags.Persist(), it also doesn't work when packing the button into a PackedScene and using PackedScene.Instanciate()

```cs
    {
        button.Connect("pressed", Callable.From(delegate { GD.Print("pressed"); }), (uint)ConnectFlags.Persist);

        button.Connect("pressed", Callable.From(Pressed), (uint)ConnectFlags.Persist);

        button.Connect("pressed", Callable.From(() => GD.Print("pressed")), (uint)ConnectFlags.Persist) ;

        button.Connect("pressed", Callable.From(() => Pressed()), (uint)ConnectFlags.Persist);

        //Node newButton = button.Duplicate();
        //container.AddChild(newButton);

        PackedScene newScene = ScenePacker.CreatePackage(button);
        Node sceneInstance = newScene.Instantiate();
        container.AddChild(sceneInstance);
    }

    public void Pressed()
    {
        GD.Print("pressed");
    }

    public class ScenePacker
    {
        public static PackedScene CreatePackage(Node node)
        {
            SetOwner(node, node);
            var package = new PackedScene();
            package.Pack(node);
            return package;
        }
        public static void SetOwner(Node node, Node owner)
        {
            foreach (Node child in node.GetChildren())
            {
                child.Owner = owner;
                SetOwner(child, owner);
            }
        }
    }
```

I've also reproduced the issue using GDScript, the signals are still not working on the duplicate

```gdscript
extends Node

@export var container: VBoxContainer
@export var button: Button

func _ready() -> void:
	button.connect("pressed", _Pressed)
	var newButton = button.duplicate()
	container.add_child(newButton)

func _Pressed() -> void:
	print("pressed")
```
